from pathlib import Path
import base64, json, zlib

path = Path('IMPLEMENTATION-BRIEF.md')
text = path.read_text(encoding='utf-8')
replacements = json.loads(zlib.decompress(base64.b64decode('')).decode('utf-8'))

for index, (old, new) in enumerate(replacements, start=1):
    if old not in text:
        raise SystemExit(f'Replacement anchor {index} not found')
    text = text.replace(old, new, 1)

path.write_text(text, encoding='utf-8')
print('Updated IMPLEMENTATION-BRIEF.md for Stage 4 Specification')
